<?php
session_start();if(!isset($_SESSION["admin"])){header("Location:index.php");exit;}require"database.php";
if(isset($_GET["approve"])){$id=(int)$_GET["approve"];$conn->query("UPDATE enrollments SET status='Approved' WHERE enrollment_id=$id");header("Location:enrollments.php");exit;}
$list=$conn->query("SELECT e.*,s.student_number,CONCAT(s.first_name,' ',s.last_name) student_name,(SELECT COALESCE(SUM(sub.units),0) FROM enrollment_subjects es JOIN subjects sub ON es.subject_id=sub.subject_id WHERE es.enrollment_id=e.enrollment_id) total_units FROM enrollments e JOIN students s ON e.student_id=s.student_id ORDER BY e.enrollment_id DESC");
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enrollment Records</title><link rel="stylesheet" href="css/style.css"></head><body><?php include"includes_nav.php";?><main class="container"><h2>Enrollment Records</h2><div class="card"><table><tr><th>Enrollment</th><th>Student</th><th>Academic Year</th><th>Semester</th><th>Units</th><th>Status</th><th>Action</th></tr><?php while($r=$list->fetch_assoc()):?><tr><td>ENR-<?=str_pad($r["enrollment_id"],5,"0",STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r["student_number"]." - ".$r["student_name"])?></td><td><?=$r["academic_year"]?></td><td><?=$r["semester"]?></td><td><?=$r["total_units"]?></td><td><span class="badge"><?=$r["status"]?></span></td><td><?php if($r["status"]!=="Approved"):?><a class="btn small" href="?approve=<?=$r["enrollment_id"]?>">Approve</a><?php else:?>Approved<?php endif;?></td></tr><?php endwhile;?></table></div></main></body></html>